// compressedCatalogFixture is independent of the import reader and has one
// compressed guest cluster, followed by holes. Only the compression stream is
// generated by a library; all QCOW2 metadata is constructed here.
func compressedCatalogFixture(t *testing.T, codec string, payload []byte) []byte {
	t.Helper()
	const cluster = 64 << 10
	var compressed []byte
	switch codec {
	case "deflate":
		var buffer bytes.Buffer
		writer, err := flate.NewWriter(&buffer, flate.DefaultCompression)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := writer.Write(payload); err != nil {
			t.Fatal(err)
		}
		if err := writer.Close(); err != nil {
			t.Fatal(err)
		}
		compressed = buffer.Bytes()
	case "zstd":
		writer, err := zstd.NewWriter(nil, zstd.WithEncoderConcurrency(1))
		if err != nil {
			t.Fatal(err)
		}
		compressed = writer.EncodeAll(payload, nil)
		if err := writer.Close(); err != nil {
			t.Fatal(err)
		}
	default:
		t.Fatalf("unknown fixture codec %q", codec)
	}
	sectors := (len(compressed) + 511) / 512
	data := catalogQCOW2("")[:5*cluster+sectors*512]
	if codec == "zstd" {
		binary.BigEndian.PutUint64(data[72:80], 1<<3)
		binary.BigEndian.PutUint32(data[100:104], 112)
		data[104] = 1
	}
	mapping := uint64(1)<<62 | uint64(sectors-1)<<54 | 5*cluster
	binary.BigEndian.PutUint64(data[4*cluster:], mapping)
	copy(data[5*cluster:], compressed)

	return data
}

//nolint:paralleltest // This test removes tools from PATH with t.Setenv.
func TestImageCatalogNormalizesWithoutExternalTools(t *testing.T) {
	// Deliberately not parallel: no executable can be discovered during import.
	t.Setenv("PATH", t.TempDir())
	for _, codec := range []string{"deflate", "zstd"} {
		t.Run(codec, func(t *testing.T) {
			payload := bytes.Repeat([]byte("desktop!"), (64<<10)/8)
			m := newTestManager(t, "graceful")
			image, err := m.ImportImage(t.Context(), codec+".qcow2",
				bytes.NewReader(compressedCatalogFixture(t, codec, payload)))
			if err != nil {
				t.Fatal(err)
			}
			path := filepath.Join(m.imageDirectory(image.ID), "disk.qcow2")
			opened, err := disk.OpenReadOnly(path)
			if err != nil {
				t.Fatal(err)
			}
			defer opened.Close()
			got := make([]byte, opened.Size())
			if n, err := opened.ReadAt(got, 0); err != nil || n != len(got) {
				t.Fatalf("read normalized image: %d, %v", n, err)
			}
			want := make([]byte, 2<<20)
			copy(want, payload)
			if !bytes.Equal(got, want) {
				t.Fatal("import changed guest bytes or filled source holes")
			}
			if image.SizeBytes >= image.VirtualSizeBytes {
				t.Fatalf("normalized image is not sparse: %+v", image)
			}
			info, err := os.Stat(path)
			if err != nil || info.Mode().Perm() != 0o600 {
				t.Fatalf("private normalized image permissions: %v, %v", info, err)
			}
		})
	}
}

func TestQCOW2NormalizationFailureKeepsSource(t *testing.T) {
	t.Parallel()
	for _, test := range []struct {
		name     string
		length   int
		limit    int64
		cancel   bool
		truncate bool
		want     error
	}{
		{name: "normalized size", length: 64 << 10, limit: 6*(64<<10) - 1, want: ErrImageTooLarge},
		{name: "overlong cluster", length: (64 << 10) + 1, limit: 2 << 20, want: ErrInvalid},
		{name: "short cluster", length: (64 << 10) - 1, limit: 2 << 20, want: ErrInvalid},
		{name: "truncated source", length: 64 << 10, limit: 2 << 20, truncate: true, want: ErrInvalid},
		{name: "cancelled", length: 64 << 10, limit: 2 << 20, cancel: true, want: context.Canceled},
	} {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			for _, codec := range []string{"deflate", "zstd"} {
				data := compressedCatalogFixture(t, codec, bytes.Repeat([]byte{0x5a}, test.length))
				if test.truncate {
					data = data[:len(data)-1]
				}
				dir := t.TempDir()
				source, destination := filepath.Join(dir, "source.qcow2"), filepath.Join(dir, "output.qcow2")
				if err := os.WriteFile(source, data, 0o600); err != nil {
					t.Fatal(err)
				}
				ctx, cancel := context.WithCancel(t.Context())
				if test.cancel {
					cancel()
				}
				err := normalizeUploadedQCOW2(ctx, source, destination, test.limit)
				cancel()
				if !errors.Is(err, test.want) {
					t.Fatalf("%s: got %v, want %v", codec, err, test.want)
				}
				if got, err := os.ReadFile(source); err != nil || !bytes.Equal(got, data) {
					t.Fatalf("failed normalization changed source: %v", err)
				}
				if _, err := os.Stat(destination); !errors.Is(err, os.ErrNotExist) {
					t.Fatalf("incomplete normalized image remains: %v", err)
				}
			}
		})
	}
}

func TestImageCatalogNormalizationFailureCleansStaging(t *testing.T) {
	t.Parallel()
	m := newTestManager(t, "graceful")
	m.config.MaxImageUploadBytes = 6*(64<<10) - 1
	fixture := compressedCatalogFixture(t, "zstd", bytes.Repeat([]byte{1}, 64<<10))
	_, err := m.ImportImage(t.Context(), "too-large.qcow2", bytes.NewReader(fixture))
	if !errors.Is(err, ErrImageTooLarge) {
		t.Fatalf("import exceeded normalized size limit: %v", err)
	}
	entries, err := os.ReadDir(filepath.Join(m.config.DataDir, "images"))
	if err != nil || len(entries) != 0 {
		t.Fatalf("failed import left catalog state: %v, %v", entries, err)
	}
}

type normalizationSource struct {
	*bytes.Reader
}

func (s normalizationSource) Extent(start, length int64) (qcow2import.Extent, error) {
	return qcow2import.Extent{Start: start, Length: length, Allocated: true}, nil
}

type cancellingImageWriter struct {
	cancel context.CancelFunc
	writes int
}

func (w *cancellingImageWriter) WriteAt(data []byte, _ int64) (int, error) {
	w.writes++
	w.cancel()

	return len(data), nil
}

func TestQCOW2ConversionCancelsBetweenWrites(t *testing.T) {
	t.Parallel()
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	source := normalizationSource{bytes.NewReader(bytes.Repeat([]byte{1}, 2<<20))}
	writer := &cancellingImageWriter{cancel: cancel}
	err := copyQCOW2Extents(ctx, source, writer, func() error { return nil })
	if !errors.Is(err, context.Canceled) || writer.writes != 1 {
		t.Fatalf("conversion continued after cancellation: writes=%d err=%v", writer.writes, err)
	}
}

func TestQCOW2ConversionDoesNotOverwriteDestination(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	source, destination := filepath.Join(dir, "source.qcow2"), filepath.Join(dir, "existing.qcow2")
	data := compressedCatalogFixture(t, "deflate", bytes.Repeat([]byte{1}, 64<<10))
	if err := os.WriteFile(source, data, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(destination, []byte("existing"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := convertUploadedQCOW2(t.Context(), source, destination, 2<<20); !errors.Is(err, os.ErrExist) {
		t.Fatalf("existing destination accepted: %v", err)
	}
	if got, err := os.ReadFile(destination); err != nil || string(got) != "existing" {
		t.Fatalf("existing destination changed: %q, %v", got, err)
	}
}

var _ io.WriterAt = (*cancellingImageWriter)(nil)

// An interrupted metadata scan must reach the HTTP layer as cancellation,
// rather than being classified as a malformed upload.
type cancellingExtentSource struct {
	normalizationSource
	cancel context.CancelFunc
}

func (s cancellingExtentSource) Extent(_, _ int64) (qcow2import.Extent, error) {
	s.cancel()

	return qcow2import.Extent{}, context.Canceled
}

func TestQCOW2ConversionCancelsDuringExtentScan(t *testing.T) {
	t.Parallel()
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	source := cancellingExtentSource{
		normalizationSource: normalizationSource{bytes.NewReader([]byte{1})},
		cancel:              cancel,
	}
	writer := &cancellingImageWriter{cancel: cancel}
	err := copyQCOW2Extents(ctx, source, writer, func() error { return nil })
	if !errors.Is(err, context.Canceled) || errors.Is(err, ErrInvalid) || writer.writes != 0 {
		t.Fatalf("cancelled extent scan: writes=%d err=%v", writer.writes, err)
	}
}
